<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'مقالات ذخیره‌شده'});const{api,media}=useShopApi();const{data,refresh}=await useAsyncData('saved-articles',()=>api<any>('/saved-articles'));async function remove(id:number){await api(`/saved-articles/${id}`,{method:'POST'});await refresh()}</script>
<template><div class="mx-auto max-w-6xl px-4 py-10"><div class="flex justify-between"><h1 class="text-2xl font-black">مقالات ذخیره‌شده</h1><NuxtLink to="/profile" class="text-sm font-bold text-brand-700">بازگشت</NuxtLink></div><div v-if="data?.data?.length" class="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><article v-for="a in data.data" :key="a.id" class="overflow-hidden rounded-2xl border bg-white"><NuxtLink :to="`/blog/${a.slug}`"><div class="aspect-video bg-stone-100"><img v-if="a.cover" :src="media(a.cover)" class="size-full object-cover"></div><div class="p-5"><h2 class="font-black">{{a.title}}</h2><p class="mt-2 line-clamp-2 text-sm leading-7 text-slate-500">{{a.excerpt}}</p></div></NuxtLink><button class="mx-5 mb-5 text-xs font-bold text-rose-600" @click="remove(a.id)">حذف از ذخیره‌ها</button></article></div><div v-else class="mt-7 rounded-2xl border border-dashed bg-white p-14 text-center text-slate-400">مقاله ذخیره‌شده‌ای ندارید.</div></div></template>
